const texasEvents=mergeDiscoveryEvents(importedTexasEvents);
const arr=x=>{try{return JSON.parse(x||'[]');}catch{return [];}};
const text=(value,fallback='Not confirmed')=>e(value||fallback);
const publicRoots=new Set(['events','guides','brands','bikes','about','editorial','community-guidelines','data-use','texas-rides','texas','trails']);
const modelCard=x=>`<article class="card"><span class="tag">${e(x.brand_name)}</span><h2><a href="${publicPath('bike',x.slug)}">${e(x.name)}</a></h2><p>${e(x.enrichment?.summary||arr(x.disciplines_json).join(' · '))}</p><p class="meta">${x.enrichment?'Selected facts checked '+e(x.enrichment.reviewed_on):'Details awaiting review'}</p></article>`;
const eventSource=(event,label)=>safeExternal(event.sourceUrl,label).replace(' target="_blank"','').replace('<a ','<a data-official-organizer ');
const eventFilter=(key,value,label=value)=>`<a href="/texas/events?${e(new URLSearchParams({[key]:value}).toString())}">${e(label)}</a>`;
const sources=urls=>`<ul>${urls.map(url=>`<li>${safeExternal(url,url)}</li>`).join('')}</ul>`;
const texasEventPath=slug=>'/texas/events/'+encodeURIComponent(slug);
const cityPath=slug=>'/texas/cities/'+encodeURIComponent(slug);
const trailPath=slug=>'/trails/'+encodeURIComponent(slug);
const clubPath=slug=>'/texas/clubs/'+encodeURIComponent(slug);
