 if(path==='/robots.txt')return response('User-agent: *\nAllow: /\n# Indexing is controlled by X-Robots-Tag response headers.\n'+(canIndex(request,env,true)?`Sitemap: ${siteOrigin(request,env)}/sitemap.xml\n`:''),200,false,'text/plain; charset=utf-8');
