 if(path.endsWith('/'))return {body:null,status:308,headers:{Location:path.slice(0,-1)+url.search}};
 if(path==='/about')return render('About Bike Portal','Practical cycling information, Texas events and tools for your own bikes.','<p>Find upcoming rides, read maintenance and preparation guides, and keep your bike notes in one place. Event organizers and manufacturers remain the authority for schedules, specifications and equipment requirements.</p><h2>Current scope</h2><p>This is a test portal. Directory information is incomplete and should be checked before travel or purchase. Community accounts and garage tools are available for testing.</p><p><a href="/editorial">How we handle sources and corrections</a> · <a href="/community-guidelines">Community participation</a></p><h2>Contact and corrections</h2><p>A public operator contact channel has not yet been supplied. This remains a public-launch requirement. For event or product questions, use the official source linked on its page. Signed-in members can report community content through its Report control.</p>');
 if(path==='/editorial')return render('Editorial standards','How Bike Portal reviews, updates, and presents cycling information.','<h2>Evidence comes first</h2><p>Event facts come from organizers or their registration pages. Product facts come from manufacturers. Unknown fields remain unknown; conflicts are described instead of silently resolved. A review date applies only to the fields listed as checked.</p><h2>Guide preparation</h2><p>Guide text has been prepared with AI assistance from cited references. No named mechanic or independent expert reviewer is claimed. Editorial update dates are distinct from source verification dates. Follow equipment-specific manufacturer instructions; get qualified help for unfamiliar work.</p><h2>Corrections and community reports</h2><p>Rider experiences are community contributions, not independently verified technical instructions. Report inappropriate community content with the Report control. A public editorial contact is still required before launch.</p><h2>Publication rules</h2><p>Unreviewed models, empty brand pages, community discussions, account tools and diagnostics remain outside search indexing. Test posts are omitted from the homepage without deleting their records. The reviewed Texas ride set has explicit recheck deadlines; expired reviews leave that selection automatically. A reference-based technical review is not a hands-on inspection or expert certification.</p>');
 if(path==='/community-guidelines')return render('Community guidelines','Share useful cycling experience respectfully.','<ul><li>No harassment, threats, impersonation, spam or another person’s private information.</li><li>Distinguish personal experience from verified facts and manufacturer instructions.</li><li>Include the original source when correcting a specification or event detail.</li><li>Do not post passwords or sensitive personal information.</li><li>Only upload images you have permission to share.</li><li>Use Report for content requiring moderator attention.</li></ul><p>These participation guidelines are not complete terms of service. Operator identity, contact, content-rights terms and age/access rules remain public-launch requirements.</p>');
 if(path==='/data-use')return render('Data use in this test portal','Current application behavior; not a complete privacy policy.','<p>Registration stores email, username and a password hash. Sign-in uses a session cookie; session tokens are stored as hashes.</p><p>Public profiles can expose display name, username, bio, location, website, avatar and garage entries. Discussions and replies are public. Saved/followed items, event plans and notifications require authentication. Reports are restricted to moderators.</p><p>Application records use Cloudflare D1; avatars use R2; production signup uses Turnstile. Replacing an avatar currently retains earlier assets. Self-service account deletion, password recovery and verification email are not implemented.</p><p>When enabled for the event-discovery pilot, first-party measurement records event-list views, selected event-detail views and the first organizer-link click per page load. It sends only the action type and page path; the application adds the batch identifier. It does not send account details or store a visitor identifier. Cloudflare processes the requests. Browser privacy signals disable this measurement; blocked or failed requests can undercount usage. This does not measure registrations or attendance.</p><p>A responsible operator, contact channel, retention periods and deletion process must be finalized before broader launch. No account-wide Cloudflare logging or retention promise is made here.</p>');
 const catalog=await readCatalog(env);
 const events=(await env.DB.prepare('SELECT * FROM events ORDER BY start_date,title').all()).results.map(editEvent);
 const eventEligible=x=>readyEvent(x,texasToday())&&x.verification_status==='verified'&&Boolean(x.venue_name&&x.address&&x.verified_on&&x.start_date>=texasToday());
 if(path==='/texas'){
  const upcoming=currentTexasEvents();
  return render('Texas cycling guide','Source-attributed Texas events, routes and city riding information from the Texas Cycling Hub catalog.',`<article class="reading"><p>This catalog contains ${e(texasEvents.length)} curated events, ${e(texasCatalogSnapshot.records.routes)} sourced routes, ${e(texasCatalogSnapshot.records.cities)} city guides, ${e(texasClubs.length)} reviewed clubs and ${e(texasCatalogSnapshot.records.highlights)} route highlights based on the Texas Cycling Hub public catalog imported on ${e(texasCatalogSnapshot.imported_at)}, with a North Texas event refresh checked October 2, 2026.</p><p>Route lines and cues are only shown where the source catalog provides them. Event details, trail conditions, closures, access rules and registration can change; use the linked official source before travelling.</p><div class="grid"><article class="card"><h2><a href="/texas/events">Texas events</a></h2><p>${upcoming.length} upcoming source-attributed events, with review dates and organizer links.</p></article><article class="card"><h2><a href="/trails">Texas routes & trails</a></h2><p>${cyclingRoutes.length} route pages with riding context, safety notes and source links.</p></article><article class="card"><h2><a href="/texas/cities">Texas city guides</a></h2><p>${texasCities.length} city pages connecting local routes and upcoming events.</p></article><article class="card"><h2><a href="/texas/clubs">Texas clubs</a></h2><p>${texasClubs.length} reviewed local organizations with official links.</p></article></div><h2>Start planning</h2><ul>${upcoming.slice(0,3).map(event=>`<li><a href="${texasEventPath(event.slug)}">${e(event.title)}</a> — ${e(event.rideDate)} in ${e(event.city)}</li>`).join('')}${cyclingRoutes.slice(0,3).map(route=>`<li><a href="${trailPath(route.slug)}">${e(route.name)}</a> — ${e(route.city)}</li>`).join('')}</ul></article>`,true,[{'@type':'CollectionPage',name:'Texas cycling guide',description:'Source-attributed Texas cycling events, routes, clubs and city riding information.'}]);
 }
 if(path.startsWith('/texas/events/')&&path.endsWith('/calendar.ics')){
  const slug=decodeURIComponent(path.slice('/texas/events/'.length,-'/calendar.ics'.length));const event=texasEvents.find(item=>item.slug===slug);if(!event||slug.includes('/'))return notFound();const validDate=value=>/^\d{4}-\d{2}-\d{2}$/.test(value||'')&&Number.isFinite(Date.parse(value+'T00:00:00Z'))&&new Date(value+'T00:00:00Z').toISOString().slice(0,10)===value; if(['postponed','tbd'].includes(event.status)||!validDate(event.rideDate)||!validDate(event.rideEndDate||event.rideDate)||(event.rideEndDate&&event.rideEndDate<event.rideDate))return response('Calendar export unavailable: confirm the event date with the organizer.',409,false,'text/plain; charset=utf-8');const end=new Date(Date.parse((event.rideEndDate||event.rideDate)+'T00:00:00Z')+86400000).toISOString().slice(0,10);
  const body=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Bike Portal//Texas public catalog//EN','CALSCALE:GREGORIAN','BEGIN:VEVENT',`UID:${event.slug}@bike-portal`,`DTSTART;VALUE=DATE:${icsDate(event.rideDate)}`,`DTEND;VALUE=DATE:${icsDate(end)}`,`SUMMARY:${icsText(event.title)}`,`LOCATION:${icsText(`${event.venue}, ${event.city}, Texas`)}`,`DESCRIPTION:${icsText(`${event.description} Official source: ${event.sourceUrl}`)}`,`URL:${event.sourceUrl}`,`STATUS:${event.status==='cancelled'?'CANCELLED':'CONFIRMED'}`,'END:VEVENT','END:VCALENDAR',''].join('\r\n');
  return response(body,200,false,'text/calendar; charset=utf-8');
 }
 if(path==='/texas/events'){
  const upcoming=filterDiscoveryEvents(texasEvents,url.searchParams,texasToday());
  const value=name=>e(url.searchParams.get(name)||'');
  const options=(values,name)=>(url.searchParams.get(name)&&!values.includes(url.searchParams.get(name))?`<option value="${e(url.searchParams.get(name))}" selected>${e(url.searchParams.get(name))} (original category)</option>`:'')+values.sort().map(item=>`<option value="${e(item)}"${url.searchParams.get(name)===item?' selected':''}>${e(item)}</option>`).join('');
  const form=`<form method="get" action="/texas/events" class="event-finder"><label class="field">Region<select name="region"><option value="">All Texas regions</option>${options([...new Set(texasEvents.map(x=>x.region))],'region')}</select></label><label class="field">Discipline<select name="discipline"><option value="">All disciplines</option>${options(eventCategoryOptions(texasEvents,'disciplines'),'discipline')}</select></label>${categorySelect(texasEvents,'formats','format','Format',url.searchParams.get('format'))}${categorySelect(texasEvents,'purposes','purpose','Purpose',url.searchParams.get('purpose'))}<label class="field">On or after<input type="date" name="from" value="${value('from')}"></label><label class="field">Event or city<input name="q" value="${value('q')}" placeholder="Name, city or county"></label><button class="btn">Filter events</button><a href="/texas/events">Clear filters</a></form>`;
  return render('Texas cycling events','Find an upcoming ride by region, discipline, date or city. Check the official organizer before making plans.',`<p><a href="/texas">Texas cycling guide</a> · <a href="/events">Bike Portal event calendar</a> · <a href="/texas/events?region=North">North Texas events</a></p>${eventMapMarkup(upcoming,[],'matching')}${form}<p role="status">${upcoming.length} upcoming event${upcoming.length===1?' matches':'s match'} your filters.</p><div class="grid">${upcoming.map(event=>`<article class="card"><span class="tag">${eventTaxonomy(event).disciplines.map(d=>eventFilter('discipline',d)).join(' / ')||'Discipline not confirmed'} · ${eventFilter('region',event.region,event.region+' Texas')}</span><h2><a href="${texasEventPath(event.slug)}">${e(event.title)}</a></h2><p><a href="${texasEventPath(event.slug)}/calendar.ics">${e(event.rideDate)}${event.rideEndDate?' – '+e(event.rideEndDate):''}</a> · ${eventLocationLink(event,event.city+', TX')}</p><p>${eventLocationLink(event,event.venue)}</p><p>${eventSource(event,event.distance)}</p><p class="meta">${eventSource(event,'Source checked '+event.checkedAt)}</p></article>`).join('')||'<p>No upcoming events match. Try another date or clear filters.</p>'}</div>`,true,[{'@type':'CollectionPage',name:'Texas cycling events'}]);
 }
 if(path.startsWith('/texas/events/')){
  const slug=decodeURIComponent(path.slice('/texas/events/'.length));const event=texasEvents.find(item=>item.slug===slug);if(!event||slug.includes('/'))return notFound();
  const schema=[{'@type':'Event',name:event.title,startDate:event.rideDate,endDate:event.rideEndDate||event.rideDate,url:siteOrigin(request,env)+path,location:{'@type':'Place',name:event.venue,address:{'@type':'PostalAddress',addressLocality:event.city,addressRegion:'TX',addressCountry:'US'}},organizer:{'@type':'Organization',name:event.organizer,url:event.sourceUrl}}];
  const fact=(label,value)=>`<dt>${label}</dt><dd>${value}</dd>`;
  const facts=fact('Date',`<a href="${texasEventPath(event.slug)}/calendar.ics">${e(event.rideDate)}${event.rideEndDate?' – '+e(event.rideEndDate):''}</a>`)+fact('Location',eventLocationLink(event,event.venue))+fact('Discipline',(event.discipline||event.rideType).split(' / ').map(d=>eventFilter('discipline',d)).join(' / '))+fact('Ride type',eventSource(event,event.rideType))+fact('Distance',eventSource(event,event.distance))+fact('Pace',eventSource(event,event.pace))+fact('Organizer',eventSource(event,event.organizer))+fact('Source checked',eventSource(event,event.checkedAt));
  return render(event.title,`${event.rideDate} · ${event.city}, Texas. Source-attributed event information.`,`<article class="reading"><dl class="facts">${facts}</dl><p>${eventSource(event,event.description)}</p>${event.notes?`<aside><h2>Details to confirm</h2><p>${eventSource(event,event.notes)}</p></aside>`:''}${eventMapMarkup(currentTexasEvents(),events)}<p><a class="btn outline" href="${texasEventPath(event.slug)}/calendar.ics">Download calendar file</a></p><h2>Before you go</h2><p>Registration, route access, event timing and conditions can change. Confirm all travel-critical details directly with the organizer.</p><p>${eventSource(event,'Visit official organizer')}</p>${event.additionalSources?.length?`<h2>Additional official sources</h2>${sources(event.additionalSources).replaceAll(' target="_blank"','')}`:''}<p><a href="/texas/events?region=${encodeURIComponent(event.region)}">More ${e(event.region)} Texas events</a></p><p><a href="/guides/event-week-bike-prep-checklist">Event-week bike preparation</a> · ${cityGuideLink(event.city)}</p></article>`,event.rideDate>=texasToday(),schema);
 }
 if(path==='/texas/clubs')return render('Texas cycling clubs','Reviewed Texas cycling organizations with official sources and documented local presence.',`<p>This directory has ${texasClubs.length} reviewed local organizations. These are public directory entries, not Bike Portal memberships or organizer claims. Confirm schedules and joining details with each club.</p><h2>Browse by city</h2><ul>${texasClubCities.map(city=>`<li><a href="${clubCityPath(city)}">${e(city)} cycling clubs</a> (${texasClubs.filter(club=>club.city===city).length})</li>`).join('')}</ul><div class="grid">${texasClubs.map(club=>`<article class="card"><span class="tag">${e(club.city)} · ${e(club.focus)}</span><h2><a href="${clubPath(club.id)}">${e(club.name)}</a></h2><p>${e(club.description)}</p><p class="meta">${e(club.meetingPlace)} · Source checked ${e(club.checkedAt)}</p></article>`).join('')}</div>`,true,[{'@type':'CollectionPage',name:'Texas cycling clubs'}]);
 if(path.startsWith('/texas/clubs/city/')){
  const slug=decodeURIComponent(path.slice('/texas/clubs/city/'.length));const city=texasClubCities.find(item=>clubCitySlug(item)===slug);if(!city||slug.includes('/'))return notFound();const clubs=texasClubs.filter(club=>club.city===city);
  return render(`${city} cycling clubs`,`Reviewed cycling organizations in ${city}, Texas.`,`<article class="reading"><p>Each entry has a reviewed official website and documented local presence. Verify current rides, eligibility and meeting locations with the club.</p><ul>${clubs.map(club=>`<li><a href="${clubPath(club.id)}">${e(club.name)}</a> — ${e(club.focus)}</li>`).join('')}</ul><p><a href="/texas/clubs">All Texas clubs</a></p></article>`,true,[{'@type':'CollectionPage',name:`${city} cycling clubs`}]);
 }
